const APPLICATION_GUIDANCE={
 "Stationary energy storage":"For stationary storage, weigh cycle life, safety, round-trip efficiency, calendar life, temperature range, availability and total system cost. Lower mass and volume constraints can make different chemistries viable than in vehicles.",
 "Electric vehicle battery":"For vehicle packs, compare usable energy per mass and volume, fast-charge behaviour, cycle life, thermal-runaway controls, cold-weather performance, pack integration and supply-chain exposure.",
 "Solar panel manufacturing":"For photovoltaic manufacturing, distinguish the cell technology (silicon, thin-film or emerging perovskite), purity requirements, conversion efficiency, degradation, encapsulation compatibility and manufacturing yield.",
 "Wind turbine components":"For wind systems, consider fatigue, corrosion, stiffness-to-weight, blade composite compatibility, drivetrain loads, repairability and service life in the intended climate.",
 "Electrical wiring and motors":"For conductors and motors, compare electrical conductivity, resistivity at operating temperature, density, thermal expansion, joining, insulation compatibility and lifecycle recycling.",
 "Building and construction":"For buildings, assess strength and stiffness by grade, fire behaviour, corrosion and moisture exposure, connection details, code compliance, embodied carbon and maintenance life.",
 "Consumer electronics":"For compact electronics, consider conductivity, thermal management, miniaturisation, solderability, corrosion, mechanical reliability, toxicity restrictions and recyclability.",
 "Industrial heat systems":"For high-temperature equipment, evaluate creep, oxidation, thermal cycling, corrosion by process media, manufacturability, inspection intervals and temperature-specific design allowables."
};
function explainMaterialForApplication(m,app,requirements=""){
 const strengths=(m.strengths||[]).slice(0,3),tradeoffs=(m.tradeoffs||[]).slice(0,3);
 const battery=/battery|storage|vehicle/i.test(app),solar=/solar|photovoltaic/i.test(app),wind=/wind/i.test(app),wire=/wiring|motor|conduct/i.test(app),building=/building|construction/i.test(app),electronics=/electronics/i.test(app),heat=/heat/i.test(app);
 let fit=`${m.name} is a plausible candidate to screen because its catalogue role is ${m.role||m.family}.`;
 if(battery&&/battery|anode|cathode|storage/i.test((m.family||"")+" "+(m.role||"")))fit=`${m.name} is relevant to ${app.toLowerCase()} because its profile is associated with battery chemistry or anode/cathode use. ${strengths[0]||"Its role warrants evaluation against cell-level requirements."}`;
 else if(solar&&/silicon|silver|aluminium|copper|semiconductor|photovoltaic/i.test(m.name+" "+m.role))fit=`${m.name} can be relevant to photovoltaic manufacturing through its semiconductor, contact, interconnect or structural role. Confirm the exact cell architecture and purity/grade before treating it as a viable choice.`;
 else if(wind&&/steel|copper|aluminium|nickel|composite|titanium/i.test(m.name+" "+m.role))fit=`${m.name} may serve a wind-system structural, electrical or corrosion-management role. The correct choice depends on whether the component is a blade, tower, fastener, generator or cable.`;
 else if(wire&&/copper|aluminium|silver|gold/i.test(m.name))fit=`${m.name} is relevant to electrical conductors or contacts. Compare conductivity at the actual operating temperature, mass, connection design and cost rather than assuming a direct one-for-one substitution.`;
 else if(building&&/steel|iron|aluminium|copper|zinc|titanium/i.test(m.name+" "+m.role))fit=`${m.name} has a plausible construction role in structural members, envelopes, services or protective systems. Selection must be tied to grade, loading, exposure and local building codes.`;
 else if(electronics&&/copper|gold|silver|silicon|tin|tantalum|palladium/i.test(m.name))fit=`${m.name} is relevant to electronic devices through semiconductor, interconnect, contact, solder or capacitor functions. Component-level purity and reliability requirements are decisive.`;
 else if(heat&&/tungsten|nickel|chromium|molybdenum|titanium|steel|platinum/i.test(m.name+" "+m.role))fit=`${m.name} may be considered for a high-temperature component or process function. Confirm oxidation, creep and corrosion performance at the real service temperature and atmosphere.`;
 const req=requirements.trim()?` Your brief also asks for: ${requirements.trim().slice(0,260)}. Check this against supplier datasheets and test evidence; this text match is not a validated fit score.`:"";
 return {fit:fit+req,why:`Why consider it: ${strengths.length?strengths.join("; "):m.role||m.family}. These attributes may support the intended function, subject to grade and design validation.`,watch:`Design checks: ${tradeoffs.length?tradeoffs.join("; "):"Confirm grade-specific limitations, processing route and lifecycle impacts."} Do not treat the catalogue as a certified specification.`,context:APPLICATION_GUIDANCE[app]||`For ${app}, define the component, duty cycle, operating temperature, mechanical/electrical loads, exposure and applicable standards before selecting a material.`};
}
