 useEffect(()=>{let live=true;fetch(API+"/api/ai/status").then(r=>r.json()).then(d=>{if(live){setAiStatus(d);if(d.providers?.ollama?.configured)setAiProvider("ollama");else if(!d.providers?.openai?.configured&&d.providers?.gemini?.configured)setAiProvider("gemini")}}).catch(()=>{});return()=>{live=false}},[]);
 useEffect(()=>{let live=true;if(selectedCountry?.iso3){fetch(API+"/api/intelligence/country/"+selectedCountry.iso3).then(r=>r.ok?r.json():null).then(d=>{if(live)setCountryEvidence(d)}).catch(()=>{if(live)setCountryEvidence(null)})}else setCountryEvidence(null);return()=>{live=false}},[selectedCountry?.iso3]);
 useEffect(()=>{let live=true;Promise.all([fetch(API+"/api/intelligence/sources"),fetch(API+"/api/intelligence/quality")]).then(async([a,b])=>{if(!a.ok||!b.ok)throw Error();return [await a.json(),await b.json()]}).then(([a,b])=>{if(live){setIntelligenceSources(a.items||[]);setIntelligenceQuality(b)}}).catch(()=>{});return()=>{live=false}},[]);
 async function loadDashboard(){setDashboardLoading(true);setDashboardError("");try{const r=await fetch(API+"/api/intelligence/dashboard");if(!r.ok)throw Error("Dashboard API unavailable");setDashboardData(await r.json())}catch(e){setDashboardError(e.message)}finally{setDashboardLoading(false)}}
