 const filteredElements=useMemo(()=>ELEMENTS.filter(e=>(e.name+" "+e.symbol+" "+e.number).toLowerCase().includes(elementSearch.toLowerCase())),[elementSearch]);
 const suggestedCandidates=useMemo(()=>{const brief=(application+" "+userRequirements).toLowerCase();const terms=brief.split(/[^a-z0-9]+/).filter(w=>w.length>3);return materials.map(m=>{const hay=(m.name+" "+m.family+" "+m.role+" "+(m.strengths||[]).join(" ")+" "+(m.tradeoffs||[]).join(" ")).toLowerCase();const score=terms.reduce((n,w)=>n+(hay.includes(w)?1:0),0);return {m,score}}).sort((a,b)=>b.score-a.score||a.m.name.localeCompare(b.m.name)).slice(0,8).map(x=>x.m)},[materials,application,userRequirements]);
 function elementsForMaterial(m){const symbols=MATERIAL_ELEMENT_MAP[m.id]||ELEMENTS.filter(e=>(m.name+" "+m.role).toLowerCase().includes(e.name.toLowerCase())).map(e=>e.symbol);return [...new Set(symbols)].map(sym=>ELEMENTS.find(e=>e.symbol===sym)).filter(Boolean)}
