 function assistantReply(raw){const q=raw.toLowerCase();let answer="I can guide you through Material Lab, country exploration, extraction methods and evidence. Tell me which task you want to complete.";let action=null;if(/atlas|reserve database|rare earth database|mineral database/.test(q)){answer="Open Global Mineral Atlas to search the first curated USGS 2026 rare-earth country records, compare reported reserves and production, and inspect the LREE/HREE taxonomy. Country splits are not inferred when the source does not publish them.";action="atlas"}else if(/satellite|remote sensing|imagery/.test(q)){answer="Open Satellite Vision for Earth observation portals, geological map layers and interpretation guidance. Satellite imagery shows surface patterns; it does not directly confirm underground ore bodies.";action="satellite"}else if(/deepcore|underground|crust|mantle|cross.section/.test(q)){answer="Open DeepCore Explorer for an educational Earth cross-section, crust-to-core layers and mining/deposit concepts. The depth view is schematic, not a measured subsurface model.";action="deepcore"}else if(/market|price|trade|supply chain/.test(q)){answer="Open Global Markets for commodity-data sources, price-history portals and critical-mineral supply-chain research. External prices must be checked at the publisher because this release does not claim a live exchange feed.";action="markets"}else if(/academy|quiz|learn|geological time/.test(q)){answer="Open NEXORA Academy for geology learning paths, a geological time overview and knowledge checks.";action="academy"}else if(/dashboard|production statistics|rankings|production trend|global production/.test(q)){answer="Open Production intelligence to filter imported mineral observations by commodity, measure, reporting year, unit and publisher. Review the trend, country ranking, publisher comparison and source-linked observation register. The dashboard only displays data actually imported into the local evidence registry.";action="dashboard"}else if(/compare|comparison|material|application|battery|solar|construction/.test(q)){answer="To compare materials: open Material Lab, choose a target application first, select at least two candidates, then press Generate comparison. Review the strengths and trade-offs side by side. The current screening is qualitative, not an engineering certification.";action="materials"}else if(/country|nation|continent|earth|globe|marker|hologram|resource/.test(q)){answer="Open Country AI analyst. Choose a country and run a source-grounded mineral, rare-earth and petroleum assessment. OpenAI/Gemini use live web grounding; Ollama is local-only and must be independently verified.";action="earth"}else if(/extract|mining|mine|recovery/.test(q)){answer="Open Extraction Lens to compare open-pit, underground and in-situ recovery. Suitability depends on deposit geometry, grade, hydrogeology, engineering and regulation; this version does not calculate site economics.";action="extraction"}else if(/requirement|brief|recommend|suggest|why.*(element|material)|application context/.test(q)){answer=`Your current application is ${application}. You have ${selectedMaterials.length} candidate(s) selected: ${materials.filter(x=>selectedMaterials.includes(x.id)).map(x=>x.name).join(", ")||"none yet"}. In Material Lab, write your use-case requirements, review the suggested candidates, add the elements/materials you want, and generate the detailed comparison. Each result explains its possible role, why it may fit, and what must be checked. ${userRequirements?"Your saved brief: "+userRequirements.slice(0,220):"You have not entered a requirement brief yet."} The recommendations are screening guidance, not engineering approval.`;action="materials"}else if(/periodic|element|atomic/.test(q)){answer="Open Material Lab → Periodic table. Choose an element tile to see its atomic number and PubChem reference, or use the linked-material chips on a candidate card to jump between the material library and the elements it contains. The element-to-material links are curated associations, not a full chemical formula database.";action="materials"}else if(/source|evidence|verified|confidence|data/.test(q)){answer="Open Evidence Centre. Use the linked geological and materials organisations, and record dataset version, date, coordinates, commodity, deposit type and evidence class. Distinguish verified occurrences from estimates and predicted prospects.";action="evidence"}else if(/help|guide|how|start|function|feature/.test(q)){answer="Start at Overview. Material Lab is for application-led comparisons; Earth Explorer is for country and resource context; Extraction Lens compares methods; Evidence Centre lists research sources. You can ask me to open any section."}setAssistantMessages(m=>[...m,{role:"user",text:raw},{role:"assistant",text:answer,action}]);if(action){setTab(action);if(action==="dashboard")loadDashboard()}setAssistantInput("")}
 async function readScreenshot(file){if(!file)return;setOcrBusy(true);setAssistantMessages(m=>[...m,{role:"user",text:"I uploaded a screenshot for visual help."}]);try{const result=await Tesseract.recognize(file,"eng");const text=result.data.text.trim().slice(0,1800);setAssistantMessages(m=>[...m,{role:"assistant",text:text?`I detected this visible text in your screenshot: “${text}”. I can use it to guide you. What part is confusing?`:"I could not read enough text in that screenshot. Try a clearer image with the relevant panel visible."}])}catch{setAssistantMessages(m=>[...m,{role:"assistant",text:"Screenshot reading could not start. You can still describe what you see and I will guide you."}])}finally{setOcrBusy(false)}}
 function exportCSV(){const chosen=comparison?.results||materials.filter(m=>selectedMaterials.includes(m.id));const rows=[["Application","User requirements","Material","Role","Why consider it","Application context","Strengths","Tradeoffs","Validation checks"],...chosen.map(m=>{const review=m.applicationReview||explainMaterialForApplication(m,application,userRequirements);return [comparison?.application||application,comparison?.requirements||userRequirements,m.name,m.role,review.fit,review.context,(m.strengths||[]).join("; "),(m.tradeoffs||[]).join("; "),review.watch]})];const csv=rows.map(r=>r.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="nexora-material-comparison.csv";a.click();URL.revokeObjectURL(a.href)}
