 const [nasaLayers,setNasaLayers]=useState([]),[nasaLayer,setNasaLayer]=useState("MODIS_Terra_CorrectedReflectance_TrueColor"),[nasaDate,setNasaDate]=useState(new Date(Date.now()-2*86400000).toISOString().slice(0,10)),[nasaImage,setNasaImage]=useState(""),[nasaError,setNasaError]=useState(""),[nasaLoading,setNasaLoading]=useState(false);
 const [marketData,setMarketData]=useState(null),[marketLoading,setMarketLoading]=useState(false),[marketError,setMarketError]=useState("");
 useEffect(()=>{if(type!=="satellite")return;let live=true;fetch(API+"/api/earth/nasa/layers").then(r=>r.ok?r.json():Promise.reject(Error("NASA layer catalogue unavailable"))).then(d=>{if(live)setNasaLayers(d.layers||[])}).catch(e=>{if(live)setNasaError(e.message)});return()=>{live=false}},[type]);
